// WorkerFilterCriteria Selects the events that trigger a worker: artifactFilterCriteria for repository actions whose metadata filterType is FILTER_REPO, schedule for SCHEDULED_EVENT (filterType SCHEDULE). Repository keys and the any* switches combine with OR.
type WorkerFilterCriteria struct {
	// ArtifactFilterCriteria Optional within this object. Selection for artifact and repository actions.
	ArtifactFilterCriteria *struct {
		// AnyFederated Optional within this object. When true, events in every federated repository trigger the worker.
		AnyFederated *bool `json:"anyFederated,omitempty"`

		// AnyLocal Optional within this object. When true, events in every local repository trigger the worker.
		AnyLocal *bool `json:"anyLocal,omitempty"`

		// AnyRemote Optional within this object. When true, events in every remote repository and its cache trigger the worker.
		AnyRemote *bool `json:"anyRemote,omitempty"`

		// ExcludePatterns Optional within this object. Ant patterns of paths that never trigger the worker; empty excludes nothing.
		ExcludePatterns *[]string `json:"excludePatterns,omitempty"`

		// IncludePatterns Optional within this object. Ant patterns of paths that trigger the worker; empty means every path.
		IncludePatterns *[]string `json:"includePatterns,omitempty"`

		// RepoKeys Optional within this object. Repository keys whose events trigger the worker.
		RepoKeys *[]string `json:"repoKeys,omitempty"`
	} `json:"artifactFilterCriteria,omitempty"`

	// Schedule Optional within this object. Cron schedule for SCHEDULED_EVENT workers; required for that action and rejected for others.
	Schedule *struct {
		// Cron Required within this object. Cron expression for when the worker runs.
		Cron string `json:"cron"`

		// Timezone Optional within this object. IANA time zone the expression is evaluated in. Defaults to UTC.
		Timezone *string `json:"timezone,omitempty"`
	} `json:"schedule,omitempty"`
}

